functions.settleOf:
const settleOf = d => {
  const m = (d || "").match(/정산[^\n:：]*[:：]\s*([\d,]+)\s*원(?:\s*\+\s*추가\s*([\d,]+)\s*원)?(?:\s*\+\s*주차\s*([\d,]+)\s*원)?/);
  const n = v => (v ? +v.replace(/,/g, "") : 0);
  return m ? { settleBase: n(m[1]), settleExtra: n(m[2]), settlePark: n(m[3]) } : { settleBase: 0, settleExtra: 0, settlePark: 0 };
};
